#!/usr/bin/env node
// Emit a Namespace vault --envdef file (one `KEY=sec_<id>` line per secret)
// for the given --mode/--provider pair, the union of a single --mode's
// providers, or explicit positional names.
//
// Mirrors scripts/provider-vars.json (generated by gen-provider-vars.ts) so
// per-job secret scoping stays the same — only the loader changes.
//
// Usage:
//   node scripts/write-vault-envdef.mjs --mode browser --provider hyperbrowser
//   node scripts/write-vault-envdef.mjs --mode ai-gateway                    # mode union
//   node scripts/write-vault-envdef.mjs INGEST_URL INGEST_SECRET            # explicit names
//
// Consumed by:
//   eval "$(nsc vault export --envdef /tmp/vault.envdef --shell=bash)"
// Each `sec_<id>` value is a placeholder; `nsc vault export` resolves each
// line against the vault (label or id) and exports the revealed value into
// the bash environment under `KEY`.
import { readFileSync } from 'node:fs';

const PLACEHOLDER = 'sec_dummy';

const argv = process.argv.slice(2);
const valueIdxs = new Set();
function flagValue(name) {
  const i = argv.indexOf(name);
  if (i === -1) return null;
  valueIdxs.add(i + 1);
  return argv[i + 1] ?? null;
}
const mode = flagValue('--mode');
const provider = flagValue('--provider');
const positional = argv.filter((a, i) => !a.startsWith('--') && !valueIdxs.has(i));

if (mode && provider) {
  const manifest = JSON.parse(readFileSync(new URL('./provider-vars.json', import.meta.url), 'utf8'));
  const modeKey = mode;
  const vars = manifest[modeKey]?.[provider];
  if (!vars) {
    console.error(`No manifest entries for ${modeKey}/${provider}. Known modes: ${Object.keys(manifest).join(', ')}`);
    process.exit(1);
  }
  process.stdout.write(vars.map((n) => `${n}=${PLACEHOLDER}\n`).join(''));
  process.exit(0);
}

if (mode) {
  // --mode without --provider: union of every provider's vars in that mode.
  const manifest = JSON.parse(readFileSync(new URL('./provider-vars.json', import.meta.url), 'utf8'));
  const modeMap = manifest[mode];
  if (!modeMap) {
    console.error(`Unknown --mode "${mode}". Known modes: ${Object.keys(manifest).join(', ')}`);
    process.exit(1);
  }
  const seen = new Set();
  for (const vars of Object.values(modeMap)) for (const v of vars) seen.add(v);
  process.stdout.write([...seen].sort().map((n) => `${n}=${PLACEHOLDER}\n`).join(''));
  process.exit(0);
}

if (positional.length) {
  process.stdout.write(positional.map((n) => `${n}=${PLACEHOLDER}\n`).join(''));
  process.exit(0);
}

console.error('Usage:');
console.error('  write-vault-envdef.mjs --mode <mode> --provider <provider>');
console.error('  write-vault-envdef.mjs --mode <mode>             # union of every provider in mode');
console.error('  write-vault-envdef.mjs NAME [NAME ...]            # explicit names');
process.exit(2);
